  // modules/ui/sections/validation_issues.js
  var MAX_ISSUES = 1e3;
  function uiSectionValidationIssues(context2, severity) {
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const map4 = context2.systems.map;
    const storage = context2.systems.storage;
    const urlhash = context2.systems.urlhash;
    const validator = context2.systems.validator;
    const viewport = context2.viewport;
    const sectionID = `issues-${severity}`;
    const section = uiSection(context2, sectionID).label(sectionLabel).shouldDisplay(sectionShouldDisplay).disclosureContent(renderDisclosureContent);
    let _issues = [];
    function sectionLabel() {
      const countText = _issues.length > MAX_ISSUES ? `${MAX_ISSUES}+` : String(_issues.length);
      const titleText = l10n.t(`issues.${severity}s`);
      return l10n.t("inspector.title_count", { title: titleText, count: countText });
    }
    function sectionShouldDisplay() {
      return _issues.length;
    }
    function renderDisclosureContent(selection2) {
      const graph = editor.staging.graph;
      const centerLoc = viewport.centerLoc();
      let issues = _issues.map(function withDistance(issue) {
        const extent2 = issue.extent(graph);
        const dist2 = extent2 ? geoSphericalDistance(centerLoc, extent2.center()) : 0;
        return Object.assign(issue, { dist: dist2 });
      }).sort((a5, b11) => a5.dist - b11.dist);
      issues = issues.slice(0, MAX_ISSUES);
      selection2.call(drawIssuesList, issues);
    }
    function drawIssuesList(selection2, issues) {
      const showAutoFix = storage.getItem("rapid-internal-feature.showAutoFix") === "true";
      let list2 = selection2.selectAll(".issues-list").data([0]);
      list2 = list2.enter().append("ul").attr("class", `layer-list issues-list ${severity}-list`).merge(list2);
      let items = list2.selectAll("li").data(issues, (d2) => d2.key);
      items.exit().remove();
      const itemsEnter = items.enter().append("li").attr("class", (d2) => `issue severity-${d2.severity}`);
      const labelsEnter = itemsEnter.append("button").attr("class", "issue-label").on("click", (d3_event, d2) => validator.focusIssue(d2)).on("mouseover", (d3_event, d2) => utilHighlightEntities(d2.entityIds, true, context2)).on("mouseout", (d3_event, d2) => utilHighlightEntities(d2.entityIds, false, context2));
      const textEnter = labelsEnter.append("span").attr("class", "issue-text");
      textEnter.append("span").attr("class", "issue-icon").each((d2, i3, nodes) => {
        select_default2(nodes[i3]).call(uiIcon(validator.getSeverityIcon(d2.severity)));
      });
      textEnter.append("span").attr("class", "issue-message");
      labelsEnter.append("span").attr("class", "issue-autofix").append("button").attr("title", l10n.t("issues.fix_one.title")).attr("class", "autofix action").on("click", clickAutoFix).call(uiIcon("#rapid-icon-wrench"));
      items = items.merge(itemsEnter).order();
      items.selectAll(".issue-message").text((d2) => d2.message(context2));
      items.selectAll(".issue-autofix").classed("hide", (d2) => !(showAutoFix && d2.autoArgs));
      const autofixable = issues.filter((issue) => issue.autoArgs);
      let autoFixAll = selection2.selectAll(".autofix-all").data(showAutoFix && autofixable.length ? [0] : []);
      autoFixAll.exit().remove();
      let autoFixAllEnter = autoFixAll.enter().insert("div", ".issues-list").attr("class", "autofix-all");
      let linkEnter = autoFixAllEnter.append("a").attr("class", "autofix-all-link").attr("href", "#");
      linkEnter.append("span").attr("class", "autofix-all-link-text").text(l10n.t("issues.fix_all.title"));
      linkEnter.append("span").attr("class", "autofix-all-link-icon").call(uiIcon("#rapid-icon-wrench"));
      autoFixAll = autoFixAll.merge(autoFixAllEnter);
      autoFixAll.selectAll(".autofix-all-link").on("click", (d3_event) => clickAutoFixAll(d3_event, autofixable));
    }
    function clickAutoFix(d3_event, issue) {
      if (d3_event) {
        d3_event.preventDefault();
        d3_event.stopPropagation();
      }
      utilHighlightEntities(issue.entityIds, false, context2);
      editor.perform(issue.autoArgs[0]);
      editor.commit({ annotation: issue.autoArgs[1], selectedIDs: issue.entityIds });
    }
    function clickAutoFixAll(d3_event, issues) {
      if (d3_event) {
        d3_event.preventDefault();
        d3_event.stopPropagation();
      }
      editor.beginTransaction();
      for (const issue of issues) {
        const action = issue.autoArgs[0];
        editor.perform(action);
      }
      editor.commit({ annotation: l10n.t("issues.fix_all.annotation") });
      editor.endTransaction();
    }
    function getOptions() {
      return {
        what: storage.getItem("validate-what") || "edited",
        where: storage.getItem("validate-where") || "all"
      };
    }
    function reloadIssues() {
      const options2 = getOptions();
      _issues = validator.getIssuesBySeverity(options2)[severity];
    }
    function isVisible() {
      return context2.container().selectAll(".map-panes .issues-pane.shown").size();
    }
    function deferredRender() {
      window.requestIdleCallback(() => {
        if (!isVisible()) return;
        reloadIssues();
        section.reRender();
      });
    }
    validator.on("validated", deferredRender);
    urlhash.on("hashchange", (currParams, prevParams) => {
      if (currParams.get("poweruser") !== prevParams.get("poweruser")) {
        deferredRender();
      }
    });
    map4.on(
      "draw",
      debounce_default(() => {
        deferredRender();
      }, 500, { leading: false, trailing: true })
      // after map has stopped moving for 500ms
    );
    return section;
  }

